Q: How can I connect the smooth curve edges of this Shape in SwiftUI? A: <p>I think the main issue with the shape is that you are not allowing space for the corners.</p>
<p>Taking the wave on the top as an example, the x-coordinate for the start of the wave needs to be inset from <code>rect.minX</code>, to allow space for the corner.</p>
<p>The adjusted values could be computed as follows:</p>
<pre class="lang-swift prettyprint-override"><code>let cornerRadius = 2 * amplitude
let adjustedMinX = rect.minX + cornerRadius
let adjustedMaxX = rect.maxX - cornerRadius
let adjustedMinY = rect.minY + cornerRadius
let adjustedMaxY = rect.maxY - cornerRadius
</code></pre>
<p>The calculations for <code>w</code> and <code>h</code> need to be updated accordingly:</p>
<pre class="lang-swift prettyprint-override"><code>let w = rect.width - (2 * cornerRadius)
let h = rect.height - (2 * cornerRadius)
</code></pre>
<p>The block for the wave along the top then changes to the following:</p>
<pre class="lang-swift prettyprint-override"><code>// MARK: - TOP
var topPoints: [CGPoint] = []
for x in stride(from: adjustedMinX, through: adjustedMaxX, by: step) {
    let t = (x - adjustedMinX) / w
    let offset = wave(t, waves: wavesX) * amplitude
    topPoints.append(CGPoint(x: x, y: rect.minY - offset))
}
</code></pre>
<p>etc.</p>
<p>This almost rectifies the problem, but the corners are still not very round.</p>
<p>It helps to tweak the control points for the corners. For example:</p>
<pre class="lang-swift prettyprint-override"><code>// LEFT-TOP corner
let corner = CGPoint(x: rect.minX - (cornerRadius / 2), y: rect.minY - (cornerRadius / 2))
path.addQuadCurve(to: first, control: corner)
</code></pre>
<p>Btw, you also had some redundant <code>if let</code> checks for optionals which were causing some warnings, these checks can simply be deleted.</p>
<p>Here is the updated shape with all changes applied:</p>
<pre class="lang-swift prettyprint-override"><code>struct WavyPostageStampShape: Shape {
    var amplitude: CGFloat = 8
    var wavesX: Int = 6
    var wavesY: Int = 10
    var phase: CGFloat = 0
    var step: CGFloat = 2

    func path(in rect: CGRect) -&gt; Path {
        var path = Path()

        let cornerRadius = 2 * amplitude
        let adjustedMinX = rect.minX + cornerRadius
        let adjustedMaxX = rect.maxX - cornerRadius
        let adjustedMinY = rect.minY + cornerRadius
        let adjustedMaxY = rect.maxY - cornerRadius
        let w = rect.width - (2 * cornerRadius)
        let h = rect.height - (2 * cornerRadius)

        func wave(_ t: CGFloat, waves: Int) -&gt; CGFloat {
            let angle = phase + t * CGFloat(waves) * 2 * .pi
            return sin(angle)
        }

        // MARK: - TOP
        var topPoints: [CGPoint] = []
        for x in stride(from: adjustedMinX, through: adjustedMaxX, by: step) {
            let t = (x - adjustedMinX) / w
            let offset = wave(t, waves: wavesX) * amplitude
            topPoints.append(CGPoint(x: x, y: rect.minY - offset))
        }

        // MARK: - RIGHT
        var rightPoints: [CGPoint] = []
        for y in stride(from: adjustedMinY, through: adjustedMaxY, by: step) {
            let t = (y - adjustedMinY) / h
            let offset = wave(t, waves: wavesY) * amplitude
            rightPoints.append(CGPoint(x: rect.maxX + offset, y: y))
        }

        // MARK: - BOTTOM
        var bottomPoints: [CGPoint] = []
        for x in stride(from: adjustedMaxX, through: adjustedMinX, by: -step) {
            let t = (adjustedMaxX - x) / w
            let offset = wave(t, waves: wavesX) * amplitude
            bottomPoints.append(CGPoint(x: x, y: rect.maxY + offset))
        }

        // MARK: - LEFT
        var leftPoints: [CGPoint] = []
        for y in stride(from: adjustedMaxY, through: adjustedMinY, by: -step) {
            let t = (adjustedMaxY - y) / h
            let offset = wave(t, waves: wavesY) * amplitude
            leftPoints.append(CGPoint(x: rect.minX - offset, y: y))
        }

        // MARK: - PATH BUILDING

        guard let first = topPoints.first else { return path }
        path.move(to: first)

        // TOP
        for p in topPoints.dropFirst() {
            path.addLine(to: p)
        }

        // TOP-RIGHT corner (quad)
        if let firstRight = rightPoints.first {
            let corner = CGPoint(x: rect.maxX + (cornerRadius / 2), y: rect.minY - (cornerRadius / 2))
            path.addQuadCurve(to: firstRight, control: corner)
        }

        // RIGHT
        for p in rightPoints.dropFirst() {
            path.addLine(to: p)
        }

        // RIGHT-BOTTOM corner
        if let firstBottom = bottomPoints.first {
            let corner = CGPoint(x: rect.maxX + (cornerRadius / 2), y: rect.maxY + (cornerRadius / 2))
            path.addQuadCurve(to: firstBottom, control: corner)
        }

        // BOTTOM
        for p in bottomPoints.dropFirst() {
            path.addLine(to: p)
        }

        // BOTTOM-LEFT corner
        if let firstLeft = leftPoints.first {
            let corner = CGPoint(x: rect.minX - (cornerRadius / 2), y: rect.maxY + (cornerRadius / 2))
            path.addQuadCurve(to: firstLeft, control: corner)
        }

        // LEFT
        for p in leftPoints.dropFirst() {
            path.addLine(to: p)
        }

        // LEFT-TOP corner
        let corner = CGPoint(x: rect.minX - (cornerRadius / 2), y: rect.minY - (cornerRadius / 2))
        path.addQuadCurve(to: first, control: corner)

        path.closeSubpath()
        return path
    }
}
</code></pre>
